+  const receipts = [];
+  if (!renderMissing) {
+    for (const packet of packets) {
+      for (const render of asArray(packet.source_page_renders)) {
+        receipts.push({
+          packet_id: packet.packet_id,
+          source_page_render_id: render.source_page_render_id,
+          output_path: render.output_path,
+          exists: fs.existsSync(resolvePath(root, render.output_path)),
+          sha256: sha256File(root, render.output_path),
+          rendered_during_run: false,
+        });
+      }
+    }
+    return receipts;
+  }
+
+  for (const packet of packets) {
+    for (const render of asArray(packet.source_page_renders)) {
+      const beforeExists = fs.existsSync(resolvePath(root, render.output_path));
+      if (!beforeExists) {
+        try {
+          await renderPdfPageWithPdfjs({
+            root,
+            sourcePdfPath: render.source_pdf_path,
+            pageNumber1Based: render.page_number_1based,
+            dpi: render.dpi ?? 200,
+            outputPath: resolvePath(root, render.output_path),
+          });
+        } catch (error) {
+          diagnostics.push({
+            code: 'source_page_render_failed',
+            severity: 'critical',
+            packet_id: packet.packet_id,
+            source_page_render_id: render.source_page_render_id,
+            output_path: render.output_path,
+            reason: error instanceof Error ? error.message : String(error),
+          });
+        }
+      }
+      const sha256 = sha256File(root, render.output_path);
+      if (render.output_sha256 && sha256 && sha256 !== render.output_sha256) {
+        diagnostics.push({
+          code: 'source_page_render_sha256_mismatch',
+          severity: 'warning',
+          packet_id: packet.packet_id,
+          source_page_render_id: render.source_page_render_id,
+          expected_sha256: render.output_sha256,
+          actual_sha256: sha256,
+        });
+      }
+      receipts.push({
+        packet_id: packet.packet_id,
+        source_page_render_id: render.source_page_render_id,
+        output_path: render.output_path,
+        exists: fs.existsSync(resolvePath(root, render.output_path)),
+        sha256,
+        rendered_during_run: !beforeExists && sha256 !== null,
+      });
+    }
+  }
+  return receipts;
+}
